// PROJETO SM3 — deterministic pre-curation.
// This is NOT the final visual redundancy decision.
// It creates a stable shortlist for the next project-level vision pass.

const rows = $input.all().map(i => i.json);

function n(v) {
  const x = Number(v);
  return Number.isFinite(x) ? x : 0;
}

const eligible = rows.filter(r =>
  String(r.ANALYSIS_STATUS || '').toUpperCase() === 'ANALYZED' &&
  String(r.STORAGE_STATUS || '').toUpperCase() === 'ONLINE' &&
  String(r.ID_PROJETO || '').trim()
);

const projects = {};

for (const r of eligible) {
  const pid = r.ID_PROJETO;
  if (!projects[pid]) projects[pid] = [];

  const editorial = n(r.EDITORIAL_SCORE);
  const technical = n(r.TECHNICAL_SCORE);
  const composition = n(r.COMPOSITION_SCORE);
  const visibility = n(r.TATTOO_VISIBILITY);

  const weighted =
    editorial * 0.45 +
    technical * 0.20 +
    composition * 0.20 +
    visibility * 0.15;

  const triage = String(r.TRIAGEM || '').toUpperCase();
  const triageAdjust =
    triage === 'SELECIONADO' ? 5 :
    triage === 'DESCARTAR' ? -30 : 0;

  projects[pid].push({
    ID_MIDIA: r.ID_MIDIA,
    TIPO: r.TIPO,
    TRIAGEM: r.TRIAGEM,
    ANALYSIS_STAGE: r.ANALYSIS_STAGE || '',
    SHOT_TYPE: r.SHOT_TYPE || '',
    EDITORIAL_SCORE: editorial,
    TECHNICAL_SCORE: technical,
    COMPOSITION_SCORE: composition,
    TATTOO_VISIBILITY: visibility,
    ANALYSIS_CONFIDENCE: n(r.ANALYSIS_CONFIDENCE),
    USAR_EM: r.USAR_EM || '',
    MELHOR_TRECHO: r.MELHOR_TRECHO || '',
    CONTEUDO_VISUAL: r['CONTEÚDO_VISUAL'] || '',
    REDUNDANCY_HINT: r.REDUNDANCY_HINT || '',
    PRECURATION_SCORE: Math.round(weighted + triageAdjust),
    redundancy_bucket:
      `${String(r.ANALYSIS_STAGE || 'UNKNOWN').toUpperCase()}|${String(r.SHOT_TYPE || 'UNKNOWN').toUpperCase()}`
  });
}

const output = [];

for (const [pid, media] of Object.entries(projects)) {
  media.sort((a, b) =>
    b.PRECURATION_SCORE - a.PRECURATION_SCORE ||
    b.ANALYSIS_CONFIDENCE - a.ANALYSIS_CONFIDENCE ||
    String(a.ID_MIDIA).localeCompare(String(b.ID_MIDIA))
  );

  const bucketCounts = {};
  for (const m of media) {
    bucketCounts[m.redundancy_bucket] = (bucketCounts[m.redundancy_bucket] || 0) + 1;
  }

  output.push({
    json: {
      project_id: pid,
      analyzed_media_count: media.length,
      shortlist: media.slice(0, Math.min(12, media.length)),
      redundancy_buckets: bucketCounts,
      next_action: media.length >= 2
        ? 'PROJECT_LEVEL_VISUAL_CURATION'
        : 'NOT_ENOUGH_MEDIA_FOR_COMPARISON',
      dry_run: true
    }
  });
}

return output.length
  ? output
  : [{json:{dry_run:true,no_work:true,message:'Nenhum projeto possui mídia ANALYZED + ONLINE.'}}];
